class SFAKVOffloadConnector(KVConnectorBase_V1, SupportsHMA):
    def __init__(self, vllm_config: VllmConfig, role: KVConnectorRole, kv_cache_config: KVCacheConfig | None = None):
        super().__init__(vllm_config=vllm_config, role=role, kv_cache_config=kv_cache_config)
        self.kv_role = vllm_config.kv_transfer_config.kv_role

        self.use_layerwise = vllm_config.kv_transfer_config.kv_connector_extra_config.get("use_layerwise", False)

        if role == KVConnectorRole.SCHEDULER:
            self.connector_scheduler = SFAKVOffloadlScheduler(vllm_config, self.use_layerwise, kv_cache_config)
        else:
            self.connector_worker = SFAKVOffloadWorker(
                vllm_config,
                self.use_layerwise,
                kv_cache_config,
            )

    ############################################################
    # Scheduler Side Methods
    ############################################################

    def get_num_new_matched_tokens(self, request: "Request", num_computed_tokens: int) -> tuple[int, bool]:
        # TODO support prefix cache
        return 0, False

    def update_state_after_alloc(self, request: "Request", blocks: "KVCacheBlocks", num_external_tokens: int):
        assert self.connector_scheduler is not None
        return self.connector_scheduler.update_state_after_alloc(request, blocks, num_external_tokens)

    def build_connector_meta(
        self,
        scheduler_output: SchedulerOutput,
    ) -> KVConnectorMetadata:
        assert self.connector_scheduler is not None
        return self.connector_scheduler.build_connector_meta(scheduler_output)

    def request_finished(
        self,
        request: "Request",
        block_ids: list[int],
    ) -> tuple[bool, dict[str, Any] | None]:
        assert self.connector_scheduler is not None
        return self.connector_scheduler.request_finished(request, block_ids)

    def request_finished_all_groups(
        self,
        request: "Request",
        block_ids: tuple[list[int], ...],
    ) -> tuple[bool, dict[str, Any] | None]:
        assert self.connector_scheduler is not None
        # sfa offload, 0 for indexer and 1 for ori kv_cache
        return self.request_finished(request, block_ids[-1])

    ############################################################
    # Worker Side Methods
    ############################################################
    def register_kv_caches(self, kv_caches: dict[str, torch.Tensor]):
        assert self.connector_worker is not None
        self.connector_worker.register_kv_caches(kv_caches)

    def start_load_kv(self, forward_context: "ForwardContext", **kwargs) -> None:
        assert self.connector_worker is not None
        metadata = self._get_connector_metadata()
        self.connector_worker.start_load_kv(metadata)

    def wait_for_layer_load(self, layer_name: str) -> None:
        # In sfa kv offload, we use prepare_lru_resident_and_load instead of wait_for_layer_load
        return

    def save_kv_layer(
        self, layer_name: str, kv_layer: torch.Tensor, attn_metadata: "AttentionMetadata", **kwargs
    ) -> None:
        self.connector_worker.save_kv_layer(layer_name)

    def wait_for_save(self):
        self.connector_worker.wait_for_save()

    def prepare_lru_resident_and_load(
        self,
        layer_name: str,
        num_tokens: int,
        num_reqs: int,
        topk_indices: torch.Tensor,
        current_slots: torch.Tensor,
        req_ids: torch.Tensor,
        token_to_req: torch.Tensor | None = None,
        capturing: bool = False,
    ) -> bool:
        return self.connector_worker.prepare_lru_resident_and_load(
            layer_name,
            num_tokens,
            num_reqs,
            topk_indices,
            current_slots,
            req_ids,
            token_to_req,
            capturing,
        )

    def set_req_ids(self, req_ids: list):
        return self.connector_worker.set_req_ids(req_ids)

    def get_finished(self, finished_req_ids: set[str]) -> tuple[set[str], set[str]]:
        # In sfa kv offload, we don't need delay free, thus no need to return finished_send/recv too.
        return (set(), set())

def _get_attention_kv_cache_dims(self, layer_name: str, kv_cache_spec: AttentionSpec) -> tuple[int, int]:
    if isinstance(kv_cache_spec, AscendMLAAttentionSpec) or isinstance(kv_cache_spec, OffloadMLAAttentionSpec):
        attn_layers = get_layers_from_vllm_config(
            self.vllm_config,
            AttentionLayerBase,
            [layer_name],
        )
        attn_layer = attn_layers[layer_name]
        if isinstance(attn_layer, MLAAttention):
            # DeepSeek MLA: K=kv_lora_rank, V=qk_rope_head_dim
            return attn_layer.kv_lora_rank, attn_layer.qk_rope_head_dim
        # CacheOnlyAttentionLayer uses AscendMLAAttentionSpec but isn't MLAAttention
        if isinstance(attn_layer, CacheOnlyAttentionLayer):
            return kv_cache_spec.head_size, kv_cache_spec.head_size
        raise TypeError(
            f"Expected MLAAttention layer for {layer_name}, got {type(attn_layer).__name__}."
        )

    head_size_v = kv_cache_spec.head_size_v if hasattr(kv_cache_spec, "head_size_v") else kv_cache_spec.head_size
    return kv_cache_spec.head_size, head_size_v

def _get_offload_sparse_c8_layout(self) -> OffloadSparseC8Layout:
    layout = getattr(self, "_offload_sparse_c8_layout_cache", None)
    if layout is None:
        hf_cfg = self.model_config.hf_text_config
        layout = compute_offload_sparse_c8_layout(
            hf_cfg.kv_lora_rank,
            hf_cfg.qk_rope_head_dim,
            hf_cfg.index_head_dim,
            self.kv_cache_dtype,
            scale_dtype=self.c8_k_scale_cache_dtype,
        )
        self._offload_sparse_c8_layout_cache = layout
    return layout

