import unittest
import tests.ut.distributed.ascend_store._mock_deps  # noqa: F401, E402
import numpy as np  # noqa: E402
import types  # noqa: E402


class TestLayerBatchBuilderSparse(unittest.TestCase):
    def test_sparse_variable_layout(self):
        from vllm_ascend.distributed.kv_transfer.kv_pool.ascend_store.kv_transfer import (
            LayerBatchBuilder,
        )
        td = types.SimpleNamespace()
        # layer0 = MLA(k,v)+idx (3 legs); layer1 = MLA only (2 legs).
        td.group_block_len = {0: [100, 20, 40, 100, 20]}
        td.group_kv_caches_base_addr = {0: [1000, 2000, 3000, 4000, 5000]}
        td.group_block_stride = {0: [100, 20, 40, 100, 20]}
        td.group_layer_offsets = {0: [0, 3]}
        td.group_layer_legs = {0: [3, 2]}
        b = LayerBatchBuilder(td, 0, 1, 160, 2)  # page=MLA+idx=160
        self.assertEqual(b._layer_offsets.tolist(), [0, 3])
        self.assertEqual(b._layer_legs.tolist(), [3, 2])
        bids = np.array([0, 1], dtype=np.int64)
        gvas = np.array([100000, 200000], dtype=np.int64)
        a0, s0, g0 = b._build_transfer_arrays(bids, gvas, 0)
        self.assertEqual(len(a0), 6)
        self.assertEqual(a0.tolist(), [1000, 2000, 3000, 1100, 2100, 3040])
        self.assertEqual(g0.tolist(), [100000, 100020, 100060, 200000, 200020, 200060])
        a1, s1, g1 = b._build_transfer_arrays(bids, gvas, 1)
        self.assertEqual(len(a1), 4)
        self.assertEqual(a1.tolist(), [4000, 5000, 4100, 5020])
        # rank_offset for L1 = 1*1*160 = 160; inner offsets for [100,20] = [0,100]
        self.assertEqual(g1.tolist(), [100160, 100260, 200160, 200260])

    def test_uniform_fallback(self):
        from vllm_ascend.distributed.kv_transfer.kv_pool.ascend_store.kv_transfer import (
            LayerBatchBuilder,
        )
        td = types.SimpleNamespace()
        # Uniform 2 legs/layer, no layer_offsets/legs tables -> uniform fallback.
        td.group_block_len = {0: [100, 20, 100, 20]}
        td.group_kv_caches_base_addr = {0: [1000, 2000, 3000, 4000]}
        td.group_block_stride = {0: [100, 20, 100, 20]}
        td.group_layer_offsets = {}
        td.group_layer_legs = {}
        b = LayerBatchBuilder(td, 0, 1, 120, 2)
        self.assertEqual(b._layer_offsets.tolist(), [0, 2])
        self.assertEqual(b._layer_legs.tolist(), [2, 2])


if __name__ == "__main__":
    unittest.main()
